import java.io.*;
import java.util.*;

public class Maxcut {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] line1 = br.readLine().split("\\s+");
        int n = Integer.parseInt(line1[0]);
        int budget = Integer.parseInt(line1[1]);

        String[] line2 = br.readLine().split("\\s+");
        int[] arr = new int[n];
        int[] signs = new int[n];

        for (int i = 0; i < n; i++) {
            arr[i] = Integer.parseInt(line2[i]);
            signs[i] = (arr[i] % 2 == 0) ? -1 : 1;
        }

        List<Integer> costs = new ArrayList<>();
        int running = 0;

        for (int i = 0; i < n - 1; i++) {
            running += signs[i];
            if (running == 0) {
                int diff = arr[i + 1] - arr[i];
                costs.add(diff >= 0 ? diff : -diff);
            }
        }

        costs.sort(Integer::compareTo);

        int accumulated = 0;
        int result = 0;

        for (int c : costs) {
            if (accumulated + c <= budget) {
                accumulated += c;
                result++;
            }
        }

        System.out.println(result);
    }
}
